def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = 0.0
    eric_prev = None
    urgent_opp = 0
    rich_opp = 0

    for oid, opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opp += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            if bid > highest_prev:
                highest_prev = bid
            if oid == 'Eric':
                eric_prev = bid

    tight_supply = supply <= 17
    loose_supply = supply >= 22
    critical_me = hp <= 3 or no_water >= 1
    fragile_me = hp <= 5

    base = DAILY_SALARY * 0.42

    if loose_supply:
        base = DAILY_SALARY * 0.28
    elif tight_supply:
        base = DAILY_SALARY * 0.62
    else:
        base = DAILY_SALARY * 0.45

    if eric_prev is not None:
        if eric_prev >= 120:
            if critical_me:
                base = max(base, DAILY_SALARY * 0.98)
            elif fragile_me:
                base = max(base, DAILY_SALARY * 0.72)
            else:
                base = min(base, DAILY_SALARY * 0.26)
        elif eric_prev >= 90:
            if tight_supply or critical_me:
                base = max(base, eric_prev * 0.78)
            else:
                base = max(base, DAILY_SALARY * 0.40)
        elif eric_prev >= 60:
            base = max(base, eric_prev + 2.0)
        else:
            base = max(base, DAILY_SALARY * 0.5)
    else:
        if highest_prev > 0:
            base = max(base, min(highest_prev + 1.5, DAILY_SALARY * 0.8))

    if urgent_opp >= 2 and not critical_me:
        base *= 0.9

    if rich_opp >= 2 and tight_supply:
        base = max(base, DAILY_SALARY * 0.75)

    if critical_me:
        base = max(base, DAILY_SALARY * 0.95)
    elif fragile_me and tight_supply:
        base = max(base, DAILY_SALARY * 0.78)

    if day >= 8:
        if hp > 5:
            base *= 0.92
        else:
            base = max(base, DAILY_SALARY * 0.82)

    reserve = 0.0
    if hp > 6:
        reserve = DAILY_SALARY * 0.6
    elif hp > 3:
        reserve = DAILY_SALARY * 0.35
    else:
        reserve = 0.0

    max_affordable = max(0.0, budget - reserve)
    if critical_me:
        max_affordable = budget

    bid = min(base, max_affordable)

    if bid < 0:
        bid = 0.0

    if bid == 0 and critical_me and budget > 0:
        bid = min(budget, DAILY_SALARY * 0.85)

    return float(round(min(bid, budget), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    alive_opps = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opps:
        # If no opponents, spend enough to secure water.
        target = min(my_status['budget'], DAILY_SALARY * 0.6)
        return max(0.0, target)

    # Extract yesterday bids for immediate reaction
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Determine urgency
    urgency = 0
    if hp <= 2.0:
        urgency += 3
    if hp <= 4.0:
        urgency += 2
    if no_water_days >= 2:
        urgency += 2
    if no_water_days >= 3:
        urgency += 3

    # Supply pressure: lower supply increases need to outbid.
    # Map supply to a [0,1] pressure factor.
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_pressure = 0.5
    else:
        supply_pressure = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    # Invert: lower supply => higher pressure
    supply_pressure = 1.0 - max(0.0, min(1.0, supply_pressure))

    # Base bid anchored to yesterday's highest bid.
    # If others were bidding near DAILY_SALARY, match/just-above to secure water.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = DAILY_SALARY * (0.75 + 0.25 * supply_pressure)
        # If we're in danger, slightly exceed the top bid trend.
        if urgency >= 4:
            bid = max(base, highest_prev_bid * 1.03)
        else:
            bid = max(base, highest_prev_bid * 0.98)
    else:
        # If yesterday bids were lower, we can be more conservative unless urgent.
        base = DAILY_SALARY * (0.45 + 0.35 * supply_pressure)
        if urgency >= 4:
            bid = max(base, DAILY_SALARY * 0.85)
        elif urgency >= 2:
            bid = max(base, DAILY_SALARY * 0.65)
        else:
            bid = base

    # Never bid more than budget; keep non-negative
    bid = max(0.0, min(budget, float(bid)))

    # If budget is too low, bid what we can but avoid overcommitting.
    if budget <= DAILY_SALARY * 0.2:
        bid = min(budget, DAILY_SALARY * 0.25)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
