        return float(min(my_status['budget'], DAILY_SALARY * 1.5))

    if supply < 18:
        return float(min(my_status['budget'], avg_opp_bid * 1.1))
    elif supply > 22:
        return float(min(my_status['budget'], avg_opp_bid * 0.7))
    else:
        return float(min(my_status['budget'], avg_opp_bid * 0.9))
